/**
 * `telamonjs add admin <module>`: scaffolds an admin-kit module into an app
 * generated by `telamonjs create` (single app or monorepo).
 *
 * Every edit is idempotent: module files are only created (an existing file
 * is kept), the Prisma block and the catalog/menu/message entries are found
 * by their marker or key before being added, and code patches skip a file
 * that already carries them. Migrations and the seed are left to the user.
 */
import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs'
import { dirname, join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'
import chalk from 'chalk'
import { addMenuItem, insertBeforeArrayClose } from '../generate/utils/menu-updater.js'
import { LOCALES, mergeMissingKeys } from '../generate/messages-writer.js'

const TEMPLATES = fileURLToPath(new URL('../../../templates', import.meta.url))

export const ADMIN_MODULES = ['audit', 'parameters', 'invitations'] as const
export type AdminModule = (typeof ADMIN_MODULES)[number]

export interface AddAdminOptions {
  dryRun?: boolean
  cwd?: string
}

/** What a run did (or, with `dryRun`, would do). Paths are relative to the app root. */
export interface AddAdminResult {
  layout: 'app' | 'monorepo'
  created: string[]
  modified: string[]
  /** Module files that already existed and were left alone */
  kept: string[]
  warnings: string[]
  nextSteps: string[]
}

export class AdminKitError extends Error {}

interface Layout {
  kind: 'app' | 'monorepo'
  /** The Next.js app (single app: the root) */
  web: string
  /** The folder of schema.prisma */
  prismaDir: string
  rbac: string
  menu: string
  /** The package.json that needs @telamonjs/data */
  dataPackage: string
}

interface ModuleSpec {
  model: string
  route: string
  menu: { titleCode: string; icon: string; permission: string }
  permissions: Array<{ code: string; category: string; description: string }>
  migration: string
  /** Monorepo: the Nest module class registered in AppModule (./modules/<module>/<module>.module) */
  nestModule: string
}

const MODULES: Record<AdminModule, ModuleSpec> = {
  audit: {
    model: 'AuditLog',
    route: 'auditoria',
    menu: { titleCode: "msg('nav.audit')", icon: 'History', permission: 'audit.read' },
    permissions: [{ code: 'audit.read', category: 'Audit', description: 'View the audit log' }],
    migration: 'add-audit',
    nestModule: 'AuditModule',
  },
  parameters: {
    model: 'Parameter',
    route: 'parametros',
    menu: { titleCode: "msg('nav.parameters')", icon: 'Settings', permission: 'parameters.read' },
    permissions: [
      { code: 'parameters.read', category: 'Parameters', description: 'View system parameters' },
      { code: 'parameters.write', category: 'Parameters', description: 'Create, edit and delete system parameters' },
    ],
    migration: 'add-parameters',
    nestModule: 'ParametersModule',
  },
  invitations: {
    model: 'Invitation',
    route: 'convites',
    menu: { titleCode: "msg('nav.invitations')", icon: 'Mail', permission: 'invitations.read' },
    permissions: [
      { code: 'invitations.read', category: 'Invitations', description: 'View invitations' },
      { code: 'invitations.write', category: 'Invitations', description: 'Invite users, resend and revoke invitations' },
    ],
    migration: 'add-invitations',
    nestModule: 'InvitationsModule',
  },
}

const ADOPT_HINT =
  'Existing hand-rolled apps adopt the runtime pieces instead: createAuditInterceptor/@SkipAudit ' +
  '(@telamonjs/data/nest), computeDiff/redactPayload (@telamonjs/data), AuditChangesViewer and ' +
  'PermissionMatrix (@telamonjs/ui), diffPermissionCatalog (@telamonjs/permissions).'

/** Single app vs monorepo, and whether the app is template-shaped at all. */
export function detectLayout(root: string): Layout {
  const monorepo = existsSync(join(root, 'apps/api')) && existsSync(join(root, 'packages/shared/prisma'))
  const web = monorepo ? join(root, 'apps/web') : root
  const layout: Layout = monorepo
    ? {
        kind: 'monorepo',
        web,
        prismaDir: join(root, 'packages/shared/prisma'),
        rbac: join(root, 'packages/shared/src/rbac.ts'),
        menu: join(web, 'src/config/menu.ts'),
        dataPackage: join(root, 'apps/api/package.json'),
      }
    : {
        kind: 'app',
        web,
        prismaDir: join(root, 'prisma'),
        rbac: join(root, 'src/rbac.ts'),
        menu: join(root, 'src/config/menu.ts'),
        dataPackage: join(root, 'package.json'),
      }

  const rel = (path: string) => relative(root, path)
  const missing: string[] = []
  if (!readIfExists(layout.rbac)?.includes('export const PERMISSIONS')) {
    missing.push(`${rel(layout.rbac)} with a PERMISSIONS catalog`)
  }
  if (!/model\s+Role\s*\{/.test(schemaSources(layout.prismaDir).join('\n'))) {
    missing.push(`a Role model in ${rel(layout.prismaDir)}`)
  }
  if (!existsSync(layout.menu)) missing.push(rel(layout.menu))
  if (missing.length) {
    throw new AdminKitError(
      `This doesn't look like an app generated by \`telamonjs create\` (missing ${missing.join(', ')}). ` +
        `\`telamonjs add admin\` only edits template-shaped apps. ${ADOPT_HINT}`
    )
  }
  return layout
}

function readIfExists(path: string): string | undefined {
  return existsSync(path) ? readFileSync(path, 'utf-8') : undefined
}

/** The folder of a multi-file schema (`prisma/schema/*.prisma`), when the app uses one. */
function schemaFolder(prismaDir: string): string | undefined {
  const folder = join(prismaDir, 'schema')
  return existsSync(folder) && statSync(folder).isDirectory() ? folder : undefined
}

function schemaSources(prismaDir: string): string[] {
  const folder = schemaFolder(prismaDir)
  if (folder) {
    return readdirSync(folder)
      .filter((file) => file.endsWith('.prisma'))
      .map((file) => readFileSync(join(folder, file), 'utf-8'))
  }
  const file = readIfExists(join(prismaDir, 'schema.prisma'))
  return file ? [file] : []
}

function walk(dir: string): string[] {
  if (!existsSync(dir)) return []
  return readdirSync(dir).flatMap((entry) => {
    const path = join(dir, entry)
    return statSync(path).isDirectory() ? walk(path) : [path]
  })
}

/** Pending writes: the content each touched file will have. */
class Plan {
  readonly files = new Map<string, string>()
  readonly kept: string[] = []
  readonly warnings: string[] = []

  constructor(readonly root: string) {}

  read(path: string): string | undefined {
    return this.files.get(path) ?? readIfExists(path)
  }

  /** Records `content` for `path` unless the file already has exactly that. */
  write(path: string, content: string): void {
    if (this.read(path) !== content) this.files.set(path, content)
  }

  /** A new file; an existing one is kept as it is. */
  create(path: string, content: string): void {
    if (this.read(path) === undefined) this.files.set(path, content)
    else this.kept.push(relative(this.root, path))
  }

  /** Touched paths, split by whether they exist on disk yet. */
  split(): { created: string[]; modified: string[] } {
    const paths = [...this.files.keys()]
    const rel = (list: string[]) => list.map((path) => relative(this.root, path)).sort()
    return {
      created: rel(paths.filter((path) => !existsSync(path))),
      modified: rel(paths.filter((path) => existsSync(path))),
    }
  }

  /**
   * Applies `edits` (exact find → replace pairs) to `path`, all or nothing,
   * unless it already contains `marker`. A missing or ambiguous anchor (an
   * edited file) leaves it untouched with a warning saying what to add.
   */
  patch(path: string, marker: string, edits: Array<[string, string]>, manual: string): void {
    const text = this.read(path)
    if (text === undefined || text.includes(marker)) return
    let next = text
    for (const [find, replace] of edits) {
      if (next.split(find).length !== 2) {
        this.warnings.push(`${relative(this.root, path)} was changed since it was generated: ${manual}`)
        return
      }
      next = next.replace(find, () => replace)
    }
    this.write(path, next)
  }
}

const before = (anchor: string, text: string): [string, string] => [anchor, text + anchor]
const after = (anchor: string, text: string): [string, string] => [anchor, anchor + text]

export function addAdmin(module: string, options: AddAdminOptions = {}): AddAdminResult {
  if (!(ADMIN_MODULES as readonly string[]).includes(module)) {
    throw new AdminKitError(`Unknown admin module "${module}". Available: ${ADMIN_MODULES.join(', ')}.`)
  }
  const name = module as AdminModule
  const spec = MODULES[name]
  const root = options.cwd ?? process.cwd()
  const layout = detectLayout(root)
  const plan = new Plan(root)
  const templates = join(TEMPLATES, 'admin', name)

  // 1. Module files: web/ goes to the Next.js app, app/ or monorepo/ to the root
  const copy = (from: string, to: string) => {
    for (const file of walk(from)) plan.create(join(to, relative(from, file)), readFileSync(file, 'utf-8'))
  }
  copy(join(templates, 'web'), layout.web)
  copy(join(templates, layout.kind), root)

  // 2. Prisma model: a marked block in schema.prisma, or its own file in a multi-file schema
  const block = readFileSync(join(templates, 'schema.prisma'), 'utf-8')
  const modelRegex = new RegExp(`model\\s+${spec.model}\\s*\\{`)
  const folder = schemaFolder(layout.prismaDir)
  const sources = schemaSources(layout.prismaDir).join('\n')
  if (modelRegex.test(sources)) {
    // A previous run left it, or the app has its own model of that name: left alone
    const ours = sources.includes(`// telamonjs:admin:${name}`) || (folder && existsSync(join(folder, `${name}.prisma`)))
    if (!ours) plan.warnings.push(`The schema already has a model ${spec.model}: kept as is. Check it has the fields the module uses.`)
  } else if (folder) {
    plan.create(join(folder, `${name}.prisma`), block)
  } else {
    const schemaPath = join(layout.prismaDir, 'schema.prisma')
    const schema = plan.read(schemaPath) ?? ''
    const begin = `// telamonjs:admin:${name} — added by \`telamonjs add admin ${name}\``
    if (!schema.includes(`// telamonjs:admin:${name}`)) {
      plan.write(schemaPath, `${schema.trimEnd()}\n\n${begin}\n${block.trimEnd()}\n// telamonjs:admin:${name}:end\n`)
    }
  }

  // 3. Permission catalog
  const rbac = plan.read(layout.rbac) ?? ''
  const entries = spec.permissions
    .filter((p) => !rbac.includes(`'${p.code}'`))
    .map((p) => `  { code: '${p.code}', category: '${p.category}', description: '${p.description}' },`)
  if (entries.length) {
    const open = rbac.match(/export const PERMISSIONS[^=]*=\s*\[/)
    const updated = open?.index === undefined ? null : insertBeforeArrayClose(rbac, open.index + open[0].length - 1, entries.join('\n'))
    if (updated) plan.write(layout.rbac, updated)
    else plan.warnings.push(`Add to PERMISSIONS in ${relative(root, layout.rbac)}:\n${entries.join('\n')}`)
  }

  // 4. Menu entry, in the Administration group
  const menu = plan.read(layout.menu) ?? ''
  try {
    const updated = addMenuItem(menu, {
      name: spec.route,
      path: `/admin/${spec.route}`,
      group: 'admin-group',
      ...spec.menu,
    })
    if (updated) plan.write(layout.menu, updated)
  } catch {
    plan.warnings.push(`Add a menu entry for /admin/${spec.route} to ${relative(root, layout.menu)}`)
  }

  // 5. i18n messages: only the keys the app lacks
  for (const locale of LOCALES) {
    const path = join(layout.web, 'messages', `${locale}.json`)
    const current = plan.read(path)
    if (current === undefined) continue
    const data = JSON.parse(current) as Record<string, unknown>
    const source = JSON.parse(readFileSync(join(templates, 'messages', `${locale}.json`), 'utf-8')) as Record<string, unknown>
    if (mergeMissingKeys(data, source)) plan.write(path, `${JSON.stringify(data, null, 2)}\n`)
  }

  // 6. @telamonjs/data (pagination helpers; audit's computeDiff/redactPayload)
  const pkg = JSON.parse(plan.read(layout.dataPackage) ?? '{}') as { dependencies?: Record<string, string> }
  if (!pkg.dependencies?.['@telamonjs/data']) {
    const range = (
      JSON.parse(readFileSync(join(TEMPLATES, 'monorepo/apps/api/package.json'), 'utf-8')) as {
        dependencies: Record<string, string>
      }
    ).dependencies['@telamonjs/data']
    pkg.dependencies = { ...pkg.dependencies, '@telamonjs/data': range }
    plan.write(layout.dataPackage, `${JSON.stringify(pkg, null, 2)}\n`)
  }

  // 7. Wiring into the existing code
  if (layout.kind === 'monorepo') {
    registerNestModule(plan, join(root, 'apps/api/src/app.module.ts'), name, spec.nestModule)
  } else if (name === 'audit') {
    patchAuditedRoutes(plan, root)
  }

  // 8. Invitations: .env.example says where the accept link comes from
  if (name === 'invitations') {
    const envPath = join(root, '.env.example')
    const env = plan.read(envPath)
    if (env !== undefined && !env.includes('telamonjs:admin:invitations')) {
      plan.write(
        envPath,
        `${env.trimEnd()}\n\n# telamonjs:admin:invitations — the accept link in invitation emails is\n# NEXTAUTH_URL/convite/<token>, so NEXTAUTH_URL must be the public URL. Mail goes\n# through ${layout.kind === 'monorepo' ? 'apps/api/src/modules/mail (MAIL_SENDER)' : 'src/lib/mail.ts (sendMail)'}: console only until you plug in a provider.\n`
      )
    }
  }

  const { created, modified } = plan.split()
  if (!options.dryRun) {
    for (const [path, content] of plan.files) {
      mkdirSync(dirname(path), { recursive: true })
      writeFileSync(path, content, 'utf-8')
    }
  }

  return {
    layout: layout.kind,
    created,
    modified,
    kept: plan.kept.sort(),
    warnings: plan.warnings,
    nextSteps: nextSteps(layout, name, spec),
  }
}

function nextSteps(layout: Layout, name: AdminModule, spec: ModuleSpec): string[] {
  const steps = [
    'pnpm install',
    `pnpm db:migrate --name ${spec.migration}${layout.kind === 'monorepo' ? '   # or pnpm db:push' : ''}`,
    'pnpm db:seed   # syncs the permission catalog; the admin role gets the new permissions',
    'Sign in again (or wait for the token refresh) to see the new menu entry',
  ]
  if (name === 'invitations') {
    steps.push(
      layout.kind === 'monorepo'
        ? 'Mail: replace ConsoleMailSender in apps/api/src/modules/mail/mail.module.ts with your provider (it only logs)'
        : 'Mail: replace the body of sendMail() in src/lib/mail.ts with your provider (it only logs)'
    )
  }
  return steps
}

/** Monorepo: the module joins AppModule's imports (audit also registers its interceptor). */
function registerNestModule(plan: Plan, path: string, name: AdminModule, className: string): void {
  const text = plan.read(path)
  const modulePath = `./modules/${name}/${name}.module`
  const manual =
    name === 'audit'
      ? `import AuditModule (${modulePath}) into AppModule and add { provide: APP_INTERCEPTOR, useClass: AuditInterceptor } (./modules/audit/audit.interceptor) to its providers`
      : `import ${className} (${modulePath}) into AppModule`
  if (text === undefined || text.includes(className)) return

  const fail = () => plan.warnings.push(`apps/api/src/app.module.ts: ${manual}`)
  const imports = [...text.matchAll(/^import[\s\S]*?from\s+['"][^'"]+['"][^\n]*\n/gm)]
  const lastImport = imports.at(-1)
  const modulesOpen = text.match(/@Module\(\{[\s\S]*?imports:\s*\[/)
  if (!lastImport || lastImport.index === undefined || !modulesOpen || modulesOpen.index === undefined) return void fail()

  const importLines =
    `import { ${className} } from '${modulePath}'\n` +
    (name === 'audit' ? "import { AuditInterceptor } from './modules/audit/audit.interceptor'\n" : '')
  const at = lastImport.index + lastImport[0].length
  let next = text.slice(0, at) + importLines + text.slice(at)
  const open = next.match(/@Module\(\{[\s\S]*?imports:\s*\[/)
  const withModule = open?.index === undefined ? null : insertBeforeArrayClose(next, open.index + open[0].length - 1, `    ${className},`)
  if (!withModule) return void fail()
  next = withModule

  if (name === 'audit') {
    const providers = next.match(/@Module\(\{[\s\S]*?providers:\s*\[/)
    const coreImport = next.match(/import \{([^}]*)\} from '@nestjs\/core'/)
    const withProvider =
      providers?.index === undefined
        ? null
        : insertBeforeArrayClose(
            next,
            providers.index + providers[0].length - 1,
            '    // Every successful, authenticated mutation → AuditLog (modules/audit)\n    { provide: APP_INTERCEPTOR, useClass: AuditInterceptor },'
          )
    if (!withProvider || !coreImport) return void fail()
    next = withProvider.replace(coreImport[0], `import {${coreImport[1].trimEnd()}, APP_INTERCEPTOR } from '@nestjs/core'`)
  }
  plan.write(path, next)
}

/**
 * Single app: Next.js has no interceptors, so the template's mutating Route
 * Handlers (users and roles) call `audit()` from src/lib/audit.ts.
 */
function patchAuditedRoutes(plan: Plan, root: string): void {
  const importLine = "import { audit } from '@/lib/audit'\n"
  const authImport = "import { requirePermission } from '@/lib/auth'\n"
  const marker = "from '@/lib/audit'"
  const api = (rel: string) => join(root, 'src/app/api', rel)
  const manual = (what: string) => `call audit() from src/lib/audit.ts after ${what}`

  plan.patch(
    api('usuarios/route.ts'),
    marker,
    [
      after(authImport, importLine),
      before(
        '  return NextResponse.json(serialize(usuario), { status: 201 })',
        "  await audit(request, currentUser, {\n    action: 'CREATE',\n    entityType: 'usuarios',\n    entityId: usuario.id,\n    changes: parsed.data,\n    statusCode: 201,\n  })\n"
      ),
    ],
    manual('creating a user (POST)')
  )

  plan.patch(
    api('usuarios/[id]/route.ts'),
    marker,
    [
      after(authImport, importLine),
      before(
        '  const { password, roleIds, active, ...rest } = parsed.data\n',
        '  const before = await prisma.user.findUnique({ where: { id }, include })\n'
      ),
      after(
        '    include,\n  })\n',
        "\n  await audit(request, currentUser, {\n    action: active === false ? 'DEACTIVATE' : active && before?.active === false ? 'ACTIVATE' : 'UPDATE',\n    entityType: 'usuarios',\n    entityId: id,\n    before: before ? { ...before, roleIds: before.roles.map(({ role }) => role.id) } : undefined,\n    changes: parsed.data,\n  })\n"
      ),
    ],
    manual('updating, activating or deactivating a user (PATCH)')
  )

  plan.patch(
    api('roles/route.ts'),
    marker,
    [
      after(authImport, importLine),
      before(
        '  return NextResponse.json(role, { status: 201 })',
        "  await audit(request, currentUser, {\n    action: 'CREATE',\n    entityType: 'roles',\n    entityId: role.id,\n    changes: parsed.data,\n    statusCode: 201,\n  })\n"
      ),
    ],
    manual('creating a role (POST)')
  )

  plan.patch(
    api('roles/[id]/route.ts'),
    marker,
    [
      after(authImport, importLine),
      before(
        "  // The holders' tokens carry the role's name and code (roles[])\n",
        "  await audit(request, currentUser, {\n    action: 'UPDATE',\n    entityType: 'roles',\n    entityId: found.id,\n    before: found,\n    changes: parsed.data,\n  })\n"
      ),
      ['export async function DELETE(_request: NextRequest', 'export async function DELETE(request: NextRequest'],
      before(
        '  return new NextResponse(null, { status: 204 })',
        "  await audit(request, currentUser, {\n    action: 'DELETE',\n    entityType: 'roles',\n    entityId: found.id,\n    changes: { code: found.code, name: found.name },\n    statusCode: 204,\n  })\n"
      ),
    ],
    manual('updating (PATCH) and deleting (DELETE) a role')
  )

  plan.patch(
    api('roles/[id]/permissions/[permissionId]/route.ts'),
    marker,
    [
      after(authImport, importLine),
      [
        'async function toggle({ params }: Params, grant: boolean)',
        'async function toggle(request: NextRequest, { params }: Params, grant: boolean)',
      ],
      before(
        "  // Every holder's token now carries the wrong permission list\n",
        "  const permission = await prisma.permission.findUnique({ where: { id: permissionId }, select: { code: true } })\n  await audit(request, currentUser, {\n    action: grant ? 'GRANT' : 'REVOKE',\n    entityType: 'roles',\n    entityId: roleId,\n    changes: { permissionId, code: permission?.code },\n    statusCode: 204,\n  })\n"
      ),
      ['export function POST(_request: NextRequest, ctx: Params) {\n  return toggle(ctx, true)', 'export function POST(request: NextRequest, ctx: Params) {\n  return toggle(request, ctx, true)'],
      ['export function DELETE(_request: NextRequest, ctx: Params) {\n  return toggle(ctx, false)', 'export function DELETE(request: NextRequest, ctx: Params) {\n  return toggle(request, ctx, false)'],
    ],
    manual('granting (POST) and revoking (DELETE) a permission')
  )
}

/** Prints a result for humans. */
export function printAddAdminResult(module: string, result: AddAdminResult, dryRun: boolean): void {
  const list = (label: string, paths: string[], color: (text: string) => string) => {
    for (const path of paths) console.log(`  ${color(label)} ${path}`)
  }
  console.log(chalk.cyan(`\ntelamonjs add admin ${module} (${result.layout === 'monorepo' ? 'monorepo' : 'single app'})${dryRun ? ' — dry run, nothing written' : ''}\n`))
  if (!result.created.length && !result.modified.length) {
    console.log(chalk.green('  Already installed: nothing to change.'))
  }
  list(dryRun ? 'would create' : 'created ', result.created, chalk.green)
  list(dryRun ? 'would modify' : 'modified', result.modified, chalk.yellow)
  list('kept    ', result.kept, chalk.gray)
  for (const warning of result.warnings) console.log(chalk.yellow(`\n  ⚠ ${warning}`))
  if (!dryRun && (result.created.length || result.modified.length)) {
    console.log(chalk.cyan('\nNext steps (nothing was migrated or seeded):'))
    for (const step of result.nextSteps) console.log(`  ${step}`)
  }
  console.log('')
}
